const $=id=>document.getElementById(id),fmt=n=>n.toLocaleString(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,unified,nodes,selected=null,focus=null,focusSource='glottolog',mode='world',display='list',positions=[],scale=1,tx=0,ty=0,width=800,height=500,dirty=false,customView=false,restoring=false,hfTask='',searchTimer=0,viewTimer=0;
const bySource=new Map(),conflictAncestors=new Set(),canvas=$('tree'),ctx=canvas.getContext('2d');
const db=()=>nodes,children=(sid,id)=>bySource.get(sid+'|'+id)||[],source=id=>unified.sources[id],title=id=>source(id)?.title||id,eligible=n=>n&&($('dialects').checked||n.level!=='dialect'),tc={},tok=h=>tc[h]||(tc[h]=getComputedStyle(document.documentElement).getPropertyValue('--c-'+h).trim()||'#'+h),col=n=>n.level==='dialect'?tok('9ba8a4'):n.level==='language'||n.level==='sample'?tok('c28051'):tok('397b7b');
// URL state: every screen state that can be shared is kept in the query string.
// Parameters: id (selected record), q (search), evidence, category, dialects=0,
// branch + src (expanded grouping and its source), view=tree, x/y/z (tree centre
// and zoom), task (Hugging Face model task), about=1 (Sources & scope dialog).
const baseTitle=document.title,detailIntro=$('detail').innerHTML;
const round=(v,d)=>{const f=10**d;return Math.round(v*f)/f};
function stateURL(){const p=new URLSearchParams(),q=$('search').value.trim();if(selected)p.set('id',selected);if(q)p.set('q',q);if($('evidence').value!=='all')p.set('evidence',$('evidence').value);if($('category').value!=='all')p.set('category',$('category').value);if(!$('dialects').checked)p.set('dialects','0');if(mode==='branch'&&focus){p.set('branch',focus);if(focusSource!=='glottolog')p.set('src',focusSource)}if(display==='chart'){p.set('view','tree');if(customView){p.set('x',String(round((width/2-tx)/scale,0)));p.set('y',String(round((height/2-ty)/scale,0)));p.set('z',String(Number(scale.toPrecision(4))))}}if(hfTask)p.set('task',hfTask);if($('sources').open)p.set('about','1');const u=new URL(location.href);u.search=p.toString();u.hash='';return u}
function saveURL(push){if(restoring||!data)return;const u=stateURL();if(u.href===location.href)return;try{history[push?'pushState':'replaceState'](null,'',u)}catch(e){}}
function viewMoved(){customView=true;requestDraw();clearTimeout(viewTimer);viewTimer=setTimeout(()=>saveURL(false),400)}
function setOption(id,v){const el=$(id);el.value=[...el.options].some(o=>o.value===v)?v:'all'}
function applyURL(initial=false){const p=new URLSearchParams(location.search),legacy=initial===true&&!location.search&&decodeURIComponent(location.hash.slice(1));if(legacy&&nodes[legacy]){restoring=true;try{select(legacy)}finally{restoring=false}history.replaceState(null,'',stateURL());return}restoring=true;try{
 $('search').value=p.get('q')||'';setOption('evidence',p.get('evidence'));setOption('category',p.get('category'));$('dialects').checked=p.get('dialects')!=='0';hfTask=p.get('task')||'';
 const id=p.get('id');selected=nodes[id]?id:null;const b=p.get('branch'),sid=p.get('src')||'glottolog';if(nodes[b]&&source(sid)){mode='branch';focus=b;focusSource=sid}else{mode='world';focus=null;focusSource='glottolog'}
 display=p.get('view')==='tree'?'chart':'list';$('outline').hidden=display!=='list';$('viewport').hidden=display==='list';$('collapse').hidden=display!=='list';
 updateResults();if(selected)renderDetail();else{$('detail').innerHTML=detailIntro;document.title=baseTitle}
 if(display==='list'){renderOutline();if(selected&&mode==='world')revealOutline(selected)}else{resize();layout();const x=parseFloat(p.get('x')),y=parseFloat(p.get('y')),z=parseFloat(p.get('z'));if([x,y,z].every(Number.isFinite)&&z>0){scale=Math.max(.0001,Math.min(20,z));tx=width/2-x*scale;ty=height/2-y*scale;customView=true;requestDraw()}}
 syncButtons();const dlg=$('sources');if(p.get('about')==='1'&&!dlg.open)dlg.showModal();else if(p.get('about')!=='1'&&dlg.open)dlg.close();
}finally{restoring=false}}
function ancestors(id){const a=[],seen=new Set();while(data.nodes[id]&&!seen.has(id)){seen.add(id);a.unshift(id);id=data.nodes[id].parent}return a}
function link(sid){const s=source(sid);return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${s.kind==='catalog'?'Catalog':'Paper'} ↗</a>`}
function native(n){return [...new Set((n.nativeNames||[]).map(r=>r.text))]}
function namesHTML(n){if(n.names===undefined){const id=n.id;window.AtlasData.names(id).then(()=>{for(const el of document.querySelectorAll('[data-names-for="'+CSS.escape(id)+'"]'))el.outerHTML=namesHTML(n)}).catch(e=>{for(const el of document.querySelectorAll('[data-names-for="'+CSS.escape(id)+'"] .small'))el.textContent=e.message+'. Reload to retry.'});return `<div data-names-for="${esc(id)}"><h3>Name in this language</h3><p class="small">Loading names…</p></div>`}const groups=new Map();for(const r of n.names||[]){if(r.placeholder)continue;let k=r.text+'\0'+r.lang;if(!groups.has(k))groups.set(k,{text:r.text,lang:r.lang,providers:new Set()});groups.get(k).providers.add(r.provider)}const own=native(n);return `<h3>Name in this language</h3>${own.length?`<div class="own-name" dir="auto">${own.map(esc).join(' / ')}</div><p class="small">Source label · ${[...new Set(n.nativeNames.map(r=>r.provider+' ['+r.lang+']'))].map(esc).join(', ')}</p>`:'<p class="missing-name">Not recorded in the imported sources. No name inferred.</p>'}<details class="recorded-names"><summary>Recorded names & spellings · ${groups.size}</summary><div class="name-list">${[...groups.values()].map(r=>`<div class="name-group"><b dir="auto">${esc(r.text)}</b><small>${esc([...r.providers].join(' · '))}${r.lang?' · '+esc(r.lang):' · language tag unspecified'}</small></div>`).join('')||'<p>No alternate names recorded.</p>'}</div></details>`}
function debateList(id){const ids=new Set([id,...ancestors(id)]);return unified.debates.filter(d=>d.appliesTo.some(x=>ids.has(x)))}
function debatesHTML(id){return debateList(id).map(d=>`<section><h3>${esc(d.title)}</h3><p class="small-disclaimer">${esc(d.status)}</p>${d.positions.map(p=>`<div class="evidence-card ${p.stance==='critique'?'conflict-card':''}"><strong>According to ${esc(p.author)}</strong><p>${esc(p.claim)}</p><span class="evidence-tag">${esc(p.publication)}</span><br><a href="${esc(p.url)}" target="_blank" rel="noopener">Paper ↗</a></div>`).join('')}<p class="small-disclaimer">${esc(d.note)}</p></section>`).join('')}
function conflictsHTML(id){const refs=unified.conflictIndex[id]||[];if(!refs.length)return '';const pairs=new Map();for(const i of refs){const c=unified.conflicts[i],k=c.a+'|'+c.b;if(!pairs.has(k))pairs.set(k,{c,count:0});pairs.get(k).count++}return `<h3>Incompatible study branches · ${pairs.size} source pairs</h3><p class="small-disclaimer">These summary clades cannot both hold on the shared sampled tips. This does not determine which study is correct. Examples below may involve a wider group containing this record.</p>${[...pairs.values()].map(({c,count})=>{const [a,b,d]=c.witness.map(x=>nodes[x].name);return `<div class="evidence-card conflict-card"><strong>${esc(title(c.a))} vs ${esc(title(c.b))}</strong><div class="conflict-witness">${esc(title(c.a))}: [${esc(a)} + ${esc(b)}] before ${esc(d)}.<br>${esc(title(c.b))}: [${esc(b)} + ${esc(d)}] before ${esc(a)}.</div><p class="small-disclaimer">Same ${c.sharedTips} sampled IDs compared · ${count} incompatible clade pair(s) involving this record.</p>${link(c.a)}${link(c.b)}<br><button data-branch="${esc(c.cladeA)}" data-sid="${esc(c.a)}">Expand A</button> <button data-branch="${esc(c.cladeB)}" data-sid="${esc(c.b)}">Expand B</button></div>`}).join('')}`}
function evidenceHTML(id){const n=nodes[id],ps=unified.placements[id]||[],seen=new Set(),unique=ps.filter(e=>{const k=e.source+'|'+e.parent+'|'+(e.sample||'');if(seen.has(k))return false;seen.add(k);return true});let out=debatesHTML(id)+conflictsHTML(id);out+='<h3>Conditional placements</h3><div class="placements">';if(data.nodes[id]&&!data.nodes[id].parent)out+=`<div class="evidence-card"><strong>According to Glottolog 5.3</strong><br>Independent top-level ${n.isolate?'isolate':'entry'}; no higher family asserted here.<br>${link('glottolog')}</div>`;
 out+=unique.map(e=>{const p=nodes[e.parent],peer=children(e.source,e.parent).filter(x=>x.child!==id).map(x=>nodes[x.child].name);const pnames=[...new Set(peer)];return `<div class="evidence-card"><strong>According to ${esc(title(e.source))}</strong><br>Placement: ${esc(p.name)}${e.sample?`<br><span class="small-disclaimer">Source sample / record: ${esc(e.sample)}</span>`:''}${pnames.length?`<br><span class="small-disclaimer">Other direct members: ${pnames.slice(0,5).map(esc).join(', ')}${pnames.length>5?' …':''}</span>`:''}<br>${link(e.source)} <button data-branch="${esc(e.parent)}" data-sid="${esc(e.source)}">Expand this grouping</button></div>`}).join('');out+='</div>';
 if(unique.length<=1)out+='<p class="small-disclaimer">No additional direct placement recorded here. This is not a consensus certificate; unimported studies may propose other relationships.</p>';
 return out;
}
function rootsFiltered(){const c=$('category').value,f=$('evidence').value;return data.roots.filter(id=>{const n=nodes[id];return eligible(n)&&(c==='all'||(c==='isolates'?n.isolate:n.category===c))&&(f==='all'||(f==='conflicts'?conflictAncestors.has(id):unified.studyIndex[id]?.length))})}
function updateResults(){if(!data)return;const q0=$('search').value.trim().toLowerCase(),q=({'日本語族':'japonic','印欧':'indo-european','インドヨーロッパ':'indo-european','琉球':'ryukyuan','手話':'sign language'}[q0]||q0),f=$('evidence').value,c=$('category').value;let all=q?Object.values(nodes).filter(n=>n.level!=='clade'&&n.searchText.includes(q)):rootsFiltered().map(id=>nodes[id]);if(q){if(f==='conflicts')all=all.filter(n=>conflictAncestors.has(n.id));if(f==='studies')all=all.filter(n=>unified.studyIndex[n.id]?.length);if(c!=='all')all=all.filter(n=>c==='isolates'?n.isolate:n.category===c);all.sort((a,b)=>(a.name.toLowerCase()===q?-1:0)-(b.name.toLowerCase()===q?-1:0)||a.name.localeCompare(b.name))}$('searchcount').textContent=fmt(all.length);$('results').innerHTML=all.slice(0,150).map(n=>`<button class="result ${selected===n.id?'selected':''}" data-select="${esc(n.id)}"><span class="dot" style="background:${col(n)}"></span><span class="name">${esc(n.name)}<small>${esc(n.isolate?'isolate':n.level)} · ${esc(n.iso||n.id)}${unified.conflictIndex[n.id]?' · competing branches':''}</small></span></button>`).join('')+(all.length>150?'<p class="small">First 150 matches. Refine your search.</p>':'')||'<p class="empty">No matching records.</p>'}
// Classification path from the top of the family down to this record: the Glottolog tree for Glottolog records, otherwise the record's own source tree.
function lineage(n){if(data.nodes[n.id])return{sid:'glottolog',ids:ancestors(n.id)};const ids=[],seen=new Set();let id=n.id;while(nodes[id]&&!seen.has(id)){seen.add(id);ids.unshift(id);id=nodes[id].parent}return{sid:n.source||'glottolog',ids}}
function lineageHTML(n){const {sid,ids}=lineage(n),up=ids.slice(0,-1),src=`<span class="lineage-source">${esc(title(sid))}</span>`;
 return `<nav class="lineage" aria-label="Classification according to ${esc(title(sid))}">${src}${up.length?`<ol class="lineage-path">${up.map(id=>`<li><button type="button" data-select="${esc(id)}">${esc(nodes[id].name)}</button></li>`).join('')}</ol>`:`<span class="lineage-top">${n.isolate?'Isolate':'Top-level'}: no higher family</span>`}</nav>`}
function renderDetail(){const n=nodes[selected];if(!n)return;let html=`<p class="eyebrow">ONE RECORD · SOURCE-CONDITIONED PLACEMENTS</p>${lineageHTML(n)}<h2>${esc(n.name)}</h2><span class="pill">${esc(n.level)}</span><span class="pill">${esc(n.id)}</span>${n.iso?`<span class="pill">ISO ${esc(n.iso)}</span>`:''}`;
 if(n.category&&n.category!=='Spoken genealogy')html+=`<p class="small-disclaimer">${esc(n.category)}${n.source?'. Source-specific grouping or sample; not a new accepted language family.':''}</p>`;
 html+=`<a class="node-detail-link" href="${esc(data.nodes[n.id]?window.LineagePaths.url(n.id):'variant-detail.html?domain=language&id='+encodeURIComponent(n.id))}">Open detail page ↗</a>`;
 html+='<section id="hf-models" class="hf-models" aria-label="Hugging Face models"></section>'+evidenceHTML(n.id)+namesHTML(n);if(data.nodes[n.id])html+=`<p><a href="https://glottolog.org/resource/languoid/id/${n.id}" target="_blank" rel="noopener">Glottolog record & references ↗</a></p>`;
 $('detail').innerHTML=html;window.LanguageModels.mount($('hf-models'),n,{task:hfTask,onTask:t=>{hfTask=t;saveURL(false)}});document.title=n.name+' · '+baseTitle;
}
function select(id,jump=true){if(!nodes[id])return;selected=id;renderDetail();updateResults();if(jump){if(data.nodes[id]){focus=null;focusSource='glottolog';mode='world';$('category').value='all';$('evidence').value='all';if(nodes[id].level==='dialect')$('dialects').checked=true;if(display==='list'){renderOutline();revealOutline(id)}else showBranch(nodes[id].children.length?id:nodes[id].parent||id,'glottolog')}else showBranch(id,nodes[id].source)}requestDraw();saveURL(true)}
let occurrence=0;
function makeNode(id,sid='glottolog',trail=new Set(),sample=''){const n=nodes[id],key=sid+'|'+id;if(trail.has(key)){const p=document.createElement('p');p.textContent='Shared reference: '+n.name;return p}const path=new Set(trail);path.add(key);const el=document.createElement('details');el.className='tree-node'+(id===selected?' selected-node':'');el.id=sid==='glottolog'?'outline-'+id:'occurrence-'+(++occurrence);const sum=document.createElement('summary'),own=native(n),ps=new Set((unified.placements[id]||[]).map(x=>x.source));sum.innerHTML=`<span class="rowname"><a href="variant-detail.html?domain=language&id=${encodeURIComponent(id)}">${esc(n.name)}</a>${sample&&sample!==n.name?`<small class="all-source-label">sample: ${esc(sample)}</small>`:''}</span>${own.length?`<span class="native-inline" dir="auto">${own.slice(0,2).map(esc).join(' / ')}</span>`:''}<span class="rowmeta">${esc(n.isolate?'isolate':n.level)}${ps.size>1?' · '+ps.size+' sources':''}${unified.conflictIndex[id]?' · ⚑':''}</span>`;el.appendChild(sum);let populated=false;
 function populate(){if(populated)return;populated=true;const info=document.createElement('div');info.className='node-information';const alt=ps.size>1||debateList(id).length||unified.conflictIndex[id];info.innerHTML=`<button data-models="${esc(id)}" class="model-shortcut">🤗 Models on Hugging Face ↗</button><p>${esc(id)} · expanded according to ${esc(title(sid))}</p><details class="recorded-names" ${alt?'open':''}><summary>Classification alternatives & evidence${alt?' ⚑':''}</summary>${evidenceHTML(id)}</details>`+namesHTML(n);el.appendChild(info);const kids=document.createElement('div');kids.className='node-children';for(const e of children(sid,id))if(eligible(nodes[e.child]))kids.appendChild(makeNode(e.child,sid,path,e.sample));
 if(sid==='glottolog')for(const a of unified.anchors[id]||[])kids.appendChild(makeSourceBranch(a,path));el.appendChild(kids)}
 el.populate=populate;el.addEventListener('toggle',e=>{if(e.target===el&&el.open)populate()});sum.addEventListener('click',e=>{if(e.target.closest('a'))return;selected=id;renderDetail();updateResults();if(!el.open)populate();requestDraw();saveURL(true)});return el;
}
function makeSourceBranch(a,trail=new Set()){const d=document.createElement('details');d.className='source-branch';const sum=document.createElement('summary');sum.innerHTML=`If following <strong>${esc(title(a.source))}</strong> → ${a.type==='catalog'?'catalog grouping':'sampled study tree'}`;d.appendChild(sum);let loaded=false;function load(){if(loaded)return;loaded=true;const wrap=document.createElement('div');wrap.innerHTML=`<p class="small-disclaimer">Alternative source-conditioned branch. This attachment is for navigation, not an additional ancestor.</p>${link(a.source)}`;wrap.appendChild(makeNode(a.root,a.source,trail));d.appendChild(wrap)}d.addEventListener('toggle',e=>{if(e.target===d&&d.open)load()});sum.addEventListener('click',()=>{if(!d.open)load()});return d}
function renderOutline(){if(!data)return;$('outline').replaceChildren();occurrence=0;if(mode==='branch'&&focus){const p=document.createElement('p');p.className='small-disclaimer';p.innerHTML='Expanded grouping according to '+esc(title(focusSource))+'. Other placements remain attached to each shared record. '+link(focusSource);$('outline').appendChild(p);const el=makeNode(focus,focusSource);$('outline').appendChild(el);el.populate();el.open=true;return}for(const id of rootsFiltered())$('outline').appendChild(makeNode(id));const intro=document.createElement('p');intro.className='root-context';intro.textContent='Cross-family / outgroup source trees · navigation only';$('outline').appendChild(intro);for(const a of unified.anchors.__unplaced__||[])$('outline').appendChild(makeSourceBranch(a))}
function revealOutline(id){for(const a of ancestors(id)){const el=$('outline-'+a);if(el?.populate){el.populate();el.open=true}}const target=$('outline-'+id);target?.scrollIntoView({block:'nearest',inline:'nearest'})}
function showBranch(id,sid){if(!nodes[id]||!source(sid))return;focus=id;focusSource=sid;mode='branch';if(display==='list')renderOutline();layout();syncButtons();saveURL(true)}
function syncButtons(){$('world').classList.toggle('active',mode==='world');$('branch').classList.toggle('active',mode==='branch');$('listview').classList.toggle('active',display==='list');$('chartview').classList.toggle('active',display==='chart')}
function layout(){if(!data)return;positions=[];let leaf=0;function walk(id,sid,depth,parent,trail,attachment=false,sample=''){if(!eligible(nodes[id])||trail.has(sid+'|'+id))return null;const p={id,sid,depth,parent,attachment,sample,x:depth*290,y:0};positions.push(p);const path=new Set(trail);path.add(sid+'|'+id);const kids=[];for(const e of children(sid,id)){const c=walk(e.child,sid,depth+1,p,path,false,e.sample);if(c)kids.push(c)}if(sid==='glottolog')for(const a of unified.anchors[id]||[]){const c=walk(a.root,a.source,depth+1,p,path,true);if(c)kids.push(c)}p.y=kids.length?kids.reduce((s,c)=>s+c.y,0)/kids.length:leaf++*29;return p}if(mode==='branch'&&focus)walk(focus,focusSource,0,null,new Set());else{for(const id of rootsFiltered()){walk(id,'glottolog',0,null,new Set());leaf+=7}for(const a of unified.anchors.__unplaced__||[]){walk(a.root,a.source,0,null,new Set());leaf+=7}}
 $('view-source').textContent='INTEGRATED · SOURCE-CONDITIONED';$('view-title').textContent=mode==='world'?'Independent roots & alternatives':nodes[focus].name;$('view-count').textContent=fmt(positions.length)+' displayed occurrences · shared IDs may appear in multiple hypotheses';syncButtons();fit()}
function bounds(){if(!positions.length)return{x:0,y:0,w:500,h:500};let minx=Infinity,miny=Infinity,maxx=-Infinity,maxy=-Infinity;for(const p of positions){minx=Math.min(minx,p.x);miny=Math.min(miny,p.y);maxx=Math.max(maxx,p.x);maxy=Math.max(maxy,p.y)}return{x:minx,y:miny,w:maxx-minx+280,h:maxy-miny+40}}
function fit(){customView=false;const b=bounds();scale=Math.max(.0001,Math.min((width-60)/Math.max(b.w,50),(height-140)/Math.max(b.h,50),1.2));tx=(width-b.w*scale)/2-b.x*scale;ty=100+(height-130-b.h*scale)/2-b.y*scale;requestDraw()}
function requestDraw(){if(display!=='chart'||dirty)return;dirty=true;requestAnimationFrame(draw)}
function draw(){dirty=false;ctx.clearRect(0,0,width,height);if(!nodes)return;for(const p of positions){const x=p.x*scale+tx,y=p.y*scale+ty,par=p.parent;if(par){const px=par.x*scale+tx,py=par.y*scale+ty;if(Math.max(px,x)<-20||Math.min(px,x)>width+20||Math.max(py,y)<-20||Math.min(py,y)>height+20)continue;ctx.beginPath();ctx.moveTo(px,py);ctx.bezierCurveTo((px+x)/2,py,(px+x)/2,y,x,y);ctx.strokeStyle=p.attachment?tok('976bb0'):p.sid==='glottolog'?col(nodes[p.id]):tok('bc9156');ctx.setLineDash(p.attachment?[4,4]:[]);ctx.globalAlpha=.5;ctx.lineWidth=p.id===selected?2:.7;ctx.stroke();ctx.setLineDash([])}if(x< -250||x>width+30||y< -30||y>height+30)continue;ctx.globalAlpha=1;ctx.fillStyle=col(nodes[p.id]);ctx.beginPath();ctx.arc(x,y,p.id===selected?4:Math.max(.4,Math.min(2.5,scale*2)),0,Math.PI*2);ctx.fill();if(scale>.55||p.id===selected){ctx.font=window.matchMedia('(max-width:700px)').matches?'16px Arial':'11px Arial';ctx.fillStyle=tok('2d463c');ctx.fillText(nodes[p.id].name+(p.attachment?' ['+title(p.sid)+']':''),x+7,y+3)}}ctx.globalAlpha=1}
function resize(){const box=$('viewport').getBoundingClientRect();if(!box.width||!box.height)return;const cx=(width/2-tx)/scale,cy=(height/2-ty)/scale;width=box.width;height=box.height;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!nodes)return;if(customView){tx=width/2-cx*scale;ty=height/2-cy*scale;requestDraw()}else fit()}
function zoom(f,x=width/2,y=height/2){const next=Math.max(.0001,Math.min(20,scale*f)),r=next/scale;tx=x-(x-tx)*r;ty=y-(y-ty)*r;scale=next;viewMoved()}
function nearest(x,y){let best=null,dist=100;for(const p of positions){const d=(x-p.x*scale-tx)**2+(y-p.y*scale-ty)**2;if(d<dist){dist=d;best=p}}return best}
function setDisplay(d){display=d;$('outline').hidden=d!=='list';$('viewport').hidden=d==='list';$('collapse').hidden=d!=='list';syncButtons();if(d==='chart'){resize();layout()}else renderOutline();saveURL(true)}
function exportSVG(){if(!positions.length)layout();const b=bounds(),pad=300,w=b.w+2*pad,h=b.h+2*pad;const out=[`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${b.x-pad} ${b.y-pad} ${w} ${h}"><title>Lang Log — source-conditioned branches</title><desc>Solid edges belong to the labeled source. Dashed edges attach alternative trees for navigation only; they do not assert ancestry. Repeated IDs are references to shared records. Full paper links and assertions are in the XML export.</desc><rect x="${b.x-pad}" y="${b.y-pad}" width="${w}" height="${h}" fill="#fafbf6"/>`];for(const p of positions){if(p.parent)out.push(`<path d="M${p.parent.x},${p.parent.y} L${p.x},${p.y}" fill="none" stroke="${p.attachment?'#976bb0':'#78917e'}" stroke-width="0.6" ${p.attachment?'stroke-dasharray="5 5"':''}/>`);out.push(`<g><title>${esc(p.id)} · according to ${esc(title(p.sid))}</title><circle cx="${p.x}" cy="${p.y}" r="2" fill="${col(nodes[p.id])}"/><text x="${p.x+5}" y="${p.y+3}" font-family="Arial" font-size="9" fill="#243c3b">${esc(nodes[p.id].name)}${p.attachment?' ['+esc(title(p.sid))+']':''}</text></g>`)}out.push('</svg>');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(out,{type:'image/svg+xml'}));a.download='integrated-language-atlas.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}
const pointers=new Map();let moved=false,down=null,pinch=0;canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.offsetX,y:e.offsetY});down={x:e.offsetX,y:e.offsetY};moved=false;if(pointers.size===2){const[a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y)}});canvas.addEventListener('pointermove',e=>{if(pointers.has(e.pointerId)){const old=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.offsetX,y:e.offsetY});if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)zoom(d/pinch,(a.x+b.x)/2,(a.y+b.y)/2);pinch=d;moved=true}else{tx+=e.offsetX-old.x;ty+=e.offsetY-old.y;if(Math.hypot(e.offsetX-down.x,e.offsetY-down.y)>4)moved=true;viewMoved()}$('tooltip').hidden=true;return}const p=nearest(e.offsetX,e.offsetY);if(p){$('tooltip').textContent=nodes[p.id].name+' · '+title(p.sid);$('tooltip').style.left=Math.max(5,Math.min(width-220,e.offsetX+12))+'px';$('tooltip').style.top=Math.max(5,e.offsetY-35)+'px';$('tooltip').hidden=false}else $('tooltip').hidden=true});canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(!moved){const p=nearest(e.offsetX,e.offsetY);if(p)select(p.id,false)}pinch=0});canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);moved=true});canvas.addEventListener('pointerleave',()=>{$('tooltip').hidden=true});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),e.offsetX,e.offsetY)},{passive:false});
document.addEventListener('click',e=>{const modelButton=e.target.closest('[data-models]');if(modelButton){selected=modelButton.dataset.models;renderDetail();updateResults();saveURL(true);$('hf-models').scrollIntoView({block:'start',behavior:'smooth'});return}const t=e.target.closest('[data-select],[data-branch]');if(!t)return;if(t.closest('#results'))setBranchMenu(false);if(t.dataset.select)select(t.dataset.select);else showBranch(t.dataset.branch,t.dataset.sid)});
$('search').oninput=()=>{updateResults();clearTimeout(searchTimer);searchTimer=setTimeout(()=>saveURL(false),400)};for(const id of ['category','evidence'])$(id).onchange=()=>{mode='world';updateResults();renderOutline();if(display==='chart')layout();saveURL(true)};$('dialects').onchange=()=>{renderOutline();if(display==='chart')layout();saveURL(true)};$('world').onclick=()=>{mode='world';focus=null;renderOutline();layout();saveURL(true)};$('branch').onclick=()=>{const id=selected||'japo1237';showBranch(id,nodes[id].source||'glottolog')};$('listview').onclick=()=>setDisplay('list');$('chartview').onclick=()=>setDisplay('chart');$('collapse').onclick=()=>document.querySelectorAll('#outline details[open]').forEach(e=>e.open=false);$('minus').onclick=()=>zoom(1/1.5);$('plus').onclick=()=>zoom(1.5);$('fit').onclick=()=>{fit();saveURL(false)};$('export').onclick=()=>{layout();exportSVG()};$('about').onclick=()=>{$('sources').showModal();saveURL(false)};$('close').onclick=()=>$('sources').close();$('sources').addEventListener('close',()=>saveURL(false));window.addEventListener('popstate',applyURL);new ResizeObserver(resize).observe($('viewport'));
window.AtlasData.load().then(async({d,u})=>{data=d;unified=u;await window.LineagePaths.init(d.nodes,d.roots);nodes={...data.nodes,...unified.extraNodes};for(const n of Object.values(nodes)){n.searchText=[n.name,n.id,n.iso,...(n.names||[]).map(r=>r.text)].join(' ').toLowerCase()}for(const e of u.assertions){if(!e.parent)continue;const k=e.source+'|'+e.parent;if(!bySource.has(k))bySource.set(k,[]);bySource.get(k).push(e)}for(const id of Object.keys(u.conflictIndex))for(const a of ancestors(id))conflictAncestors.add(a);updateResults();renderOutline();layout();const randomPool=Object.values(data.nodes).filter(n=>['language','dialect'].includes(n.level)&&n.category!=='Bookkeeping').map(n=>n.id);$('random-record').disabled=!randomPool.length;$('random-record').onclick=()=>{const pool=randomPool.filter(id=>id!==selected);const id=pool[Math.floor(Math.random()*pool.length)];if(!id)return;select(id);setBranchMenu(false);$('detail').scrollIntoView({behavior:'smooth',block:'start'});};$('coverage').innerHTML=`${fmt(u.stats.glottologRecords)} Glottolog records retained; ${fmt(u.stats.canonicalRecords)} canonical records including source-specific clades/samples. All ${u.stats.summaryTrees} discovered Phlorest dataset summary trees imported, plus WALS.<br>${fmt(u.stats.assertions)} source-tagged root/parent assertions. ${fmt(u.stats.topologicalConflicts)} incompatible clade pairs across study trees involve ${fmt(u.stats.recordsWithConflicts)} canonical records.<br>This is coverage of the imported corpus, not every publication worldwide.`;$('source-register').innerHTML=Object.values(u.sources).filter(s=>s.kind==='study').map(s=>`<div class="registry-source"><strong>${esc(s.title)}</strong><br>${esc(s.citation)}<br><a href="${esc(s.url)}" target="_blank" rel="noopener">Paper ↗</a> · <a href="${esc(s.dataset)}" target="_blank" rel="noopener">Source tree & data ↗</a><small>${esc(s.family)} · ${esc(s.license)} · summary tree imported</small>${s.interpretationNote?'<p>'+esc(s.interpretationNote)+'</p>':''}</div>`).join('');applyURL(true);window.AtlasData.search().then(t=>{for(const [id,s] of Object.entries(t))if(nodes[id])nodes[id].searchText+=' '+s;if($('search').value.trim())updateResults()}).catch(console.error)}).catch(e=>{$('outline').innerHTML='<p class="load-error">'+esc(e.message)+'. Reload to retry.</p>';$('view-count').textContent=e.message;console.error(e)});

const branchMenu=$('branch-menu'),branchSearch=$('branch-search');
function setBranchMenu(open,focusSearch=false){
 branchSearch.classList.toggle('mobile-open',open);
 branchMenu.setAttribute('aria-expanded',String(open));
 branchMenu.querySelector('.menu-status').textContent=open?'Close':'Open';
 branchMenu.querySelector('path').setAttribute('d',open?'M6 6l12 12M6 18L18 6':'M4 6h16M4 12h16M4 18h16');
 if(focusSearch&&open)$('search').focus({preventScroll:true});
 else if(!open&&branchSearch.contains(document.activeElement)&&window.matchMedia('(max-width:700px)').matches)branchMenu.focus({preventScroll:true});
}
branchMenu.addEventListener('click',()=>setBranchMenu(branchMenu.getAttribute('aria-expanded')!=='true',true));
branchSearch.addEventListener('keydown',e=>{if(e.key==='Escape'&&window.matchMedia('(max-width:700px)').matches){setBranchMenu(false);branchMenu.focus({preventScroll:true})}});

// The canvas tree reads its colours from the theme tokens; redraw when the theme changes.
document.addEventListener('themechange',()=>{for(const k in tc)delete tc[k];requestDraw()});
